#include <stdio.h>
int main(void) {
    FILE *w = fopen("lines.txt", "w");
    fputs("first line\nsecond line\n", w);
    fclose(w);
    FILE *r = fopen("lines.txt", "r");
    char line[64];
    while (fgets(line, sizeof line, r)) {   /* fgets 把换行符也读进来 */
        printf("LINE: %s", line);
    }
    fclose(r);
    return 0;
}
